Ns=sorted(res)
for T in times:
    print("t=%.1f L1 orders:"%T,["%.2f"%np.log2(res[a][T]['L1']/res[b][T]['L1']) for a,b in zip(Ns,Ns[1:])])
X,Y,h,out=keep; ts=[0.0]+times
